import type { Metadata } from 'next'
import { revalidateTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export const metadata: Metadata = {
  title: 'Admin · Product Catalog',
  description: 'Browse the product catalog and trigger a sync from upstream ERP/PIM.',
}

export default async function Page() {
  const products = await getAllProducts()

  async function syncCatalog(formData: FormData) {
    'use server'
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '1rem',
        }}
      >
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '0.25rem 0 0', color: '#666' }}>
            {products.length} products · cached &amp; tagged as{' '}
            <code>products</code>
          </p>
        </div>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '1rem' }}>
        <thead>
          <tr>
            <th
              style={{ textAlign: 'left', borderBottom: '1px solid #ddd', padding: '0.5rem' }}
            >
              ID
            </th>
            <th
              style={{ textAlign: 'left', borderBottom: '1px solid #ddd', padding: '0.5rem' }}
            >
              Name
            </th>
            <th
              style={{
                textAlign: 'right',
                borderBottom: '1px solid #ddd',
                padding: '0.5rem',
              }}
            >
              Price
            </th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td style={{ borderBottom: '1px solid #eee', padding: '0.5rem' }}>
                {product.id}
              </td>
              <td style={{ borderBottom: '1px solid #eee', padding: '0.5rem' }}>
                {product.name}
              </td>
              <td
                style={{
                  borderBottom: '1px solid #eee',
                  padding: '0.5rem',
                  textAlign: 'right',
                }}
              >
                ${product.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

